contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= t <= 10**4",
      "description": "The number of test cases is between 1 and 10^4."
    },
    {
      "id": "P2",
      "expression": "all(1 <= n <= 2 * 10**5 for n in [int(line.split()[0]) for line in stdin.splitlines()[1::3]])",
      "description": "Each test case has a number of vertices n between 1 and 2 * 10^5."
    },
    {
      "id": "P3",
      "expression": "all(len(b) == n for n, b in zip([int(line.split()[0]) for line in stdin.splitlines()[1::3]], [list(map(int, line.split())) for line in stdin.splitlines()[2::3]]))",
      "description": "The length of the ancestor array b matches the number of vertices n for each test case."
    },
    {
      "id": "P4",
      "expression": "all(all(1 <= bi <= n for bi in b) for n, b in zip([int(line.split()[0]) for line in stdin.splitlines()[1::3]], [list(map(int, line.split())) for line in stdin.splitlines()[2::3]]))",
      "description": "Each ancestor bi in the array b is between 1 and n for each test case."
    },
    {
      "id": "P5",
      "expression": "all(len(p) == n for n, p in zip([int(line.split()[0]) for line in stdin.splitlines()[1::3]], [list(map(int, line.split())) for line in stdin.splitlines()[4::3]]))",
      "description": "The length of the permutation array p matches the number of vertices n for each test case."
    },
    {
      "id": "P6",
      "expression": "all(all(1 <= pi <= n for pi in p) for n, p in zip([int(line.split()[0]) for line in stdin.splitlines()[1::3]], [list(map(int, line.split())) for line in stdin.splitlines()[4::3]]))",
      "description": "Each vertex pi in the permutation array p is between 1 and n for each test case."
    },
    {
      "id": "P7",
      "expression": "all(len(set(p)) == n for n, p in zip([int(line.split()[0]) for line in stdin.splitlines()[1::3]], [list(map(int, line.split())) for line in stdin.splitlines()[4::3]]))",
      "description": "The permutation array p contains n distinct vertices for each test case."
    },
    {
      "id": "P8",
      "expression": "sum([int(line.split()[0]) for line in stdin.splitlines()[1::3]]) <= 2 * 10**5",
      "description": "The sum of the number of vertices n over all test cases does not exceed 2 * 10^5."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "all(isinstance(result, list) and len(result) == n for n, result in zip([int(line.split()[0]) for line in stdin.splitlines()[1::3]], [list(map(int, line.split())) for line in stdout.splitlines()]))",
      "description": "The output for each test case is a list of n integers."
    },
    {
      "id": "Q2",
      "expression": "all(all(0 <= wi <= 10**9 for wi in result) for result in [list(map(int, line.split())) for line in stdout.splitlines()])",
      "description": "Each edge weight wi in the output is between 0 and 10^9."
    },
    {
      "id": "Q3",
      "expression": "all(result[p[i] - 1] == 0 for n, b, p, result in zip([int(line.split()[0]) for line in stdin.splitlines()[1::3]], [list(map(int, line.split())) for line in stdin.splitlines()[2::3]], [list(map(int, line.split())) for line in stdin.splitlines()[4::3]], [list(map(int, line.split())) for line in stdout.splitlines()]) if result != [-1])",
